// Platzhalter-Füllung als Fallback; produktiv übernimmt der LLM-Node davor
// die Feinformulierung, die Vorlage bleibt die Leitplanke.
const d = $input.first().json;
const vorlage = d.vorlage ?? 'Sehr geehrte Damen und Herren,\n\nfür ein Objekt ({{assetklasse}}, {{region}}) suchen wir ausgewählte Investoren. Details nach NDA.\n\nMit freundlichen Grüßen\nSEIL Real Estate';
const text = vorlage
  .replaceAll('{{assetklasse}}', d.objekt?.assetklasse ?? '')
  .replaceAll('{{region}}', d.objekt?.region ?? '');
return [{ json: { objektId: d.objektId, entwurf: text, status: 'wartet_auf_freigabe', erstellt: new Date().toISOString() } }];
